        Objects.requireNonNull(key, "'key' cannot be null.");
        Objects.requireNonNull(iv, "'iv' cannot be null.");
        Objects.requireNonNull(additionalAuthenticatedData, "'additionalAuthenticatedData' cannot be null.");

