    private static class Triplet<T, U, V> {
        private final T first;
        private final U second;
        private final V third;

        Triplet(T first, U second, V third) {
            this.first = first;
            this.second = second;
            this.third = third;
        }

        T getFirst() {
            return first;
        }

        U getSecond() {
            return second;
        }

        V getThird() {
            return third;
        }
    }
